/*
 * Known-answer probe for the illumos SMBIOS parser: opens kat/table.bin (generated by
 * gen_fixtures.py) through smbios_bufopen() and prints what the library decodes. test.sh compares the
 * output with kat/expected.txt. Built with the project's normal flags (no sanitizers).
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <sys/smbios.h>

#define	S(p)	((p) != NULL ? (p) : "(null)")

static int
visit(smbios_hdl_t *shp, const smbios_struct_t *sp, void *arg)
{
	smbios_info_t info;
	int *n = arg;

	(*n)++;
	printf("struct id=0x%x type=%u", (unsigned)sp->smbstr_id, sp->smbstr_type);

	switch (sp->smbstr_type) {
	case SMB_TYPE_SYSTEM:
		if (smbios_info_common(shp, sp->smbstr_id, &info) == 0)
			printf(" system mfg=%s product=%s version=%s serial=%s",
			    S(info.smbi_manufacturer), S(info.smbi_product), S(info.smbi_version),
			    S(info.smbi_serial));
		break;
	case SMB_TYPE_CHASSIS: {
		smbios_chassis_t c;

		if (smbios_info_chassis(shp, sp->smbstr_id, &c) == 0 &&
		    smbios_info_common(shp, sp->smbstr_id, &info) == 0)
			printf(" chassis mfg=%s ver=%s serial=%s asset=%s type=%u lock=%u oem=0x%x u=%u cords=%u sku=%s",
			    S(info.smbi_manufacturer), S(info.smbi_version), S(info.smbi_serial),
			    S(info.smbi_asset), c.smbc_type, c.smbc_lock, (unsigned)c.smbc_oemdata,
			    c.smbc_uheight, c.smbc_cords, S(c.smbc_sku));
		break;
	}
	case SMB_TYPE_MEMDEVICE: {
		smbios_memdevice_t m;

		if (smbios_info_memdevice(shp, sp->smbstr_id, &m) == 0)
			printf(" memdevice size=%llu twidth=%u dwidth=%u speed=%u form=%u type=%u dloc=%s bloc=%s",
			    (unsigned long long)m.smbmd_size, m.smbmd_twidth, m.smbmd_dwidth,
			    m.smbmd_speed, m.smbmd_form, m.smbmd_type, S(m.smbmd_dloc), S(m.smbmd_bloc));
		if (smbios_info_common(shp, sp->smbstr_id, &info) == 0)
			printf(" mfg=%s serial=%s part=%s", S(info.smbi_manufacturer),
			    S(info.smbi_serial), S(info.smbi_part));
		break;
	}
	case SMB_TYPE_OEMSTR: {
		const char *s[8];
		int cnt = smbios_info_strtab(shp, sp->smbstr_id, 0, NULL);

		printf(" oemstrings=%d", cnt);
		if (cnt > 0 && cnt <= 8 && smbios_info_strtab(shp, sp->smbstr_id, cnt, s) == cnt)
			for (int i = 0; i < cnt; i++)
				printf(" [%s]", s[i]);
		break;
	}
	default:
		break;
	}
	printf("\n");
	return (0);
}

int
main(int argc, char **argv)
{
	smbios_entry_t ent;
	smbios_hdl_t *shp;
	smbios_bios_t bios;
	smbios_system_t sys;
	smbios_lang_t lang;
	smbios_version_t v;
	long len;
	FILE *f;
	uint8_t *buf;
	int err, n = 0;

	if (argc != 2) {
		fprintf(stderr, "usage: smbios_kat table.bin\n");
		return (2);
	}
	f = fopen(argv[1], "rb");
	if (f == NULL)
		return (2);
	fseek(f, 0, SEEK_END);
	len = ftell(f);
	fseek(f, 0, SEEK_SET);
	buf = malloc(len);
	if (buf == NULL || fread(buf, 1, len, f) != (size_t)len)
		return (2);
	fclose(f);

	memset(&ent, 0, sizeof (ent));
	memcpy(ent.ep30.smbe_eanchor, SMB3_ENTRY_EANCHOR, SMB3_ENTRY_EANCHORLEN);
	ent.ep30.smbe_elen = sizeof (ent.ep30);
	ent.ep30.smbe_major = 3;
	ent.ep30.smbe_minor = 0;
	ent.ep30.smbe_stlen = len;

	shp = smbios_bufopen(&ent, buf, len, SMB_VERSION, SMB_O_NOCKSUM | SMB_O_NOVERS, &err);
	if (shp == NULL) {
		printf("open failed: %s\n", smbios_errmsg(err));
		return (1);
	}

	smbios_info_smbios_version(shp, &v);
	printf("smbios version %u.%u\n", v.smbv_major, v.smbv_minor);
	if (smbios_info_bios(shp, &bios) != SMB_ERR)
		printf("bios vendor=%s version=%s reldate=%s segment=0x%x romsize=%u cflags=0x%llx biosv=%u.%u\n",
		    S(bios.smbb_vendor), S(bios.smbb_version), S(bios.smbb_reldate), bios.smbb_segment,
		    bios.smbb_romsize, (unsigned long long)bios.smbb_cflags,
		    bios.smbb_biosv.smbv_major, bios.smbb_biosv.smbv_minor);
	if (smbios_info_system(shp, &sys) != SMB_ERR) {
		printf("system uuidlen=%u wakeup=%u sku=%s family=%s uuid=",
		    sys.smbs_uuidlen, sys.smbs_wakeup, S(sys.smbs_sku), S(sys.smbs_family));
		for (int i = 0; i < sys.smbs_uuidlen; i++)
			printf("%02x", sys.smbs_uuid[i]);
		printf("\n");
	}
	if (smbios_info_lang(shp, &lang) != SMB_ERR)
		printf("lang cur=%s fmt=%u num=%u\n", S(lang.smbla_cur), lang.smbla_fmt, lang.smbla_num);

	(void) smbios_iter(shp, visit, &n);
	printf("structures=%d\n", n);
	smbios_close(shp);
	free(buf);
	return (0);
}
